 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1
    bg = max(freq, key=freq.get)

    # Uniform non-background rows/columns are lattice separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    sep_colors = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}

    def spans(size, separators):
        bounds = [-1] + separators + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)
    cells = []
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            marks = [(dr, dc, grid[r0 + dr][c0 + dc])
                     for dr in range(r1 - r0) for dc in range(c1 - c0)
                     if grid[r0 + dr][c0 + dc] != bg
                     and grid[r0 + dr][c0 + dc] not in sep_colors]
            cells.append((ri, ci, r0, r1, c0, c1, marks))

    source = max(cells, key=lambda cell: len(cell[6]))
    _, _, _, sr1, _, sc1, motif = source
    sh, sw = sr1 - source[2], sc1 - source[4]
    out = [row[:] for row in grid]
